const MAX_PER_STATE = 5;
const stateItems = $('State Pages List').all();
const out = [];
$input.all().forEach((item, i) => {
  const state = stateItems[i] ? stateItems[i].json.state : 'राज्य';
  const html = String(item.json.data || '');
  const re = /<script type="application\/ld\+json">([\s\S]*?)<\/script>/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    if (m[1].indexOf('"ItemList"') === -1) continue;
    try {
      const data = JSON.parse(m[1]);
      const list = (data.itemListElement || []).slice(0, MAX_PER_STATE);
      for (const el of list) {
        if (el && el.url && el.name) out.push({ json: { state, title: el.name, link: el.url } });
      }
    } catch (e) {}
    break;
  }
});
return out;

