const dec = (s) => String(s).replace(/&#0?39;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
const esc = (s) => dec(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const byState = {};
const order = [];
for (const it of $input.all()) {
  const s = it.json.state;
  if (!byState[s]) { byState[s] = []; order.push(s); }
  byState[s].push(it.json);
}
return order.map((s) => {
  const lines = byState[s].map((n, idx) => (idx + 1) + '. <a href="' + n.link + '">' + esc(n.title) + '</a>');
  return { json: { state: s, text: '<b>' + esc(s) + ' की ताज़ा खबरें</b>\n\n' + lines.join('\n\n') } };
});
